TRACK.workshops=[
{type:'BRISE-GLACE',title:'D’accord ou pas ? Les mythes sur le renseignement à l’ONU',body:`<p><b>Durée :</b> 15 min · <b>Format :</b> plénière, cartes ou mains levées.</p><ol><li>La Politique de 2019 donne une définition formelle du renseignement aux fins du maintien de la paix.</li><li>Un petit remerciement en espèces à un villageois serviable est acceptable s’il n’est pas clandestin.</li><li>Le MICM est l’endroit où l’analyse de la mission est rédigée.</li><li>Un U2 peut utiliser un canal de renseignement national lorsque le système de la mission est lent.</li><li>En cas d’urgence, les vérifications préalables au partage peuvent être omises.</li><li>Tout ce qui est sensible dans une mission relève du renseignement aux fins du maintien de la paix.</li></ol>`,
answers:`<ol><li><b>Pas d’accord.</b> La section Termes définit des mots connexes, mais pas le PKI lui-même. Enseignez l’objet énoncé au par. 5.</li><li><b>Pas d’accord.</b> Les Directives HPKI interdisent de remettre de l’argent ou des cadeaux à des sources ou à leurs proches en échange d’informations.</li><li><b>Pas d’accord.</b> Le MICM dirige et supervise le cycle. Il ne procède pas à l’analyse.</li><li><b>Pas d’accord.</b> Le principe d’indépendance exige que le système soit autonome par rapport à tout système national de renseignement.</li><li><b>Pas d’accord.</b> L’urgence ne dispense pas de ces étapes (Directives sur le partage, 8.1.7). Les menaces imminentes sont traitées en priorité, mais n’en sont pas exemptées.</li><li><b>Pas d’accord.</b> La Politique s’applique uniquement aux éléments gérés dans le cycle du PKI. Les rapports courants sont distincts, même lorsqu’ils sont sensibles.</li></ol>`},
{type:'CONSTRUCTION DU CYCLE',title:'Construire le cycle : de la question du Chef de mission à la décision',body:`<p><b>Durée :</b> 60 min · petits groupes avec cartes.</p><p>Le Chef de mission de la MINUKA demande : « Le site de déplacés d’Oru sera-t-il attaqué avant le jour de marché ? » Construisez le parcours allant de cette question à une réponse présentée en séance d’information.</p><ol><li>Placez les cinq étapes dans l’ordre et indiquez qui dirige chacune d’elles.</li><li>Transformez la question en CCIR, en PIR et en RFI.</li><li>Quels documents et quelle instance devraient régir cette démarche ?</li><li>Que se passe-t-il si la diffusion intervient après le jour de marché ?</li></ol>`,
answers:`<ol><li>Direction (Chef de mission et MICM) ; Acquisition (entités chargées de cette tâche dans le cadre du MISP) ; Examen et collationnement ; Analyse (JMAC, U2 et autres, mais pas le MICM) ; Diffusion (au décideur, en temps utile).</li><li><b>CCIR :</b> ce que le responsable doit savoir pour décider de la protection d’Oru. <b>PIR :</b> « Quel groupe a l’intention de marcher sur Oru, et quand ? » <b>RFI :</b> demande adressée par un G2 de secteur au JMAC pour obtenir des données récentes sur les incidents. Les besoins sont généralement formulés sous forme de questions.</li><li>Le plan d’acquisition d’informations de la mission (MIAP), le plan d’appui (MISP) et le plan ISP de la force, conforme à celui-ci. Les priorités sont validées par le MICM ou par un conseil de gestion du PKI.</li><li>Le produit n’a aucune valeur pour la décision. Le respect des délais peut justifier une estimation brève avec une incertitude déclarée plutôt qu’un rapport complet mais tardif.</li></ol>`},
{type:'TEST DES LIGNES ROUGES',title:'S’arrêter ou continuer ? Douze propositions venues du terrain',body:`<p><b>Durée :</b> 45 min · les équipes lèvent une carte verte, orange ou rouge et citent la règle. <b>Formateur :</b> ne jugez que la règle. N’abordez pas la manière dont un acte interdit serait accompli.</p><ol><li>Lire les déclarations publiques d’un groupe armé pour répondre à un PIR.</li><li>Utiliser un faux profil en ligne pour parler à ses membres.</li><li>Demander à un garçon de 15 ans ce qu’il a vu près du camp.</li><li>Écouter un agriculteur qui donne spontanément des nouvelles à un point d’arrêt de patrouille.</li><li>Offrir du crédit téléphonique à un ancien du village pour des nouvelles utiles.</li><li>Faire franchir une frontière à un UAS de la mission sans autorisation de l’État hôte.</li><li>Utiliser un rapport sur un site trouvé avec votre téléphone personnel.</li><li>Demander à un policier de l’État hôte de vous remettre les dossiers de son ministère.</li><li>Transmettre directement à l’UNDSS une menace visant le personnel de l’ONU.</li><li>Utiliser des fragments de bombe pour appuyer une frappe contre une personne nommément désignée.</li><li>S’habiller en travailleur humanitaire pour entrer dans un village.</li><li>Consigner votre évaluation selon laquelle un rapport est peu solide.</li></ol>`,
answers:`<p><b>Vert :</b> 1 (OPKI, première méthode à envisager), 4 (contact fortuit non dirigé), 9 (Politique, 11.3.2), 12 (bonne analyse).</p><p><b>Orange, s’arrêter et renvoyer :</b> 8 (employés de l’État hôte uniquement avec des approbations préalables ; ne jamais demander à quiconque d’enfreindre la loi). 6 (l’autorisation de l’État hôte doit toujours être prise en considération ; le MISP et le conseiller juridique décident).</p><p><b>Rouge :</b> 2 (pas de faux comptes, OPKI 11.8). 3 (les enfants ne doivent pas être utilisés comme sources ; si un enfant révèle un risque, renvoyez aux services de protection de l’enfance). 5 (pas de cadeaux, HPKI 12.14). 7 (les éléments obtenus sur du matériel personnel ne doivent pas être utilisés). 10 (le TPKI ne sert pas au ciblage cinétique, sauf mandat explicite visant à atténuer les dommages causés aux civils). 11 (ne pas dissimuler son emploi à l’ONU ; pas de fausse identité).</p><p><b>Bilan :</b> face au rouge, la bonne réaction n’est pas de trouver une façon plus habile de procéder. Arrêtez-vous, consignez, informez votre chaîne hiérarchique et trouvez un moyen licite.</p>`},
{type:'ATELIER D’ANALYSE',title:'Hypothèses concurrentes : qui menace Oru ?',body:`<p><b>Durée :</b> 75 min · groupes de 4–5 personnes avec une matrice sur tableau de conférence.</p><p>Éléments : a) des messages radio qualifient les habitants d’Oru de traîtres ; b) un contact non vérifié affirme qu’un groupe armé viendra avant le jour de marché ; c) les commerçants n’empruntent plus la route du nord ; d) deux femmes ont indiqué à une équipe des affaires civiles que des jeunes hommes ont quitté leurs villages ; e) l’armée affirme que le groupe se rassemble ; f) des images satellitaires achetées dans le commerce ne montrent aucun nouveau camp ; g) les attaques passées ont eu lieu à la récolte, et non les jours de marché.</p><p>Hypothèses : H1 un groupe armé prépare une attaque ; H2 un différend local est attisé par de fausses rumeurs ; H3 l’armée exagère la menace pour obtenir l’appui de la mission.</p><ol><li>Construisez la matrice. Quels éléments sont les plus utiles ?</li><li>Quel biais est le plus probable ?</li><li>Qu’écririez-vous à l’intention du Chef de mission ?</li></ol>`,
answers:`<ol><li>L’ACH consiste à chercher à réfuter. Un élément compatible avec les trois hypothèses, comme a), est peu utile. Les plus utiles sont ceux qui correspondent à une hypothèse et pas aux autres : f) et g) vont à l’encontre de H1 ; d) doit être examiné plutôt qu’écarté.</li><li>Le biais de confirmation, le biais de source en faveur de l’armée et la tendance à minimiser ce que rapportent les femmes. La superposition est également un risque : b) et e) peuvent avoir la même origine.</li><li>Par exemple : « Nous estimons, avec un degré de confiance faible à modéré, qu’une attaque est possible mais n’est pas encore indiquée ; la rumeur est pour l’instant le facteur le mieux étayé. Indicateurs qui modifieraient cette évaluation : ... Nous recommandons dès maintenant des patrouilles de présence et un dialogue avec la population, et un réexamen dans 48 heures. » Maintenez une séparation visible entre les faits et le jugement.</li></ol>`},
{type:'EXERCICE SUR LES PRODUITS',title:'Réécrire l’INTSUM : fait, commentaire, évaluation',body:`<p><b>Durée :</b> 45 min · individuellement, puis par deux.</p><p>Un projet indique : « Le groupe armé X attaquera bientôt la base de Tessa, comme tout le monde le sait en ville. Il possède des drones. Le gouvernement est derrière lui. Recommandons une action énergique. »</p><ol><li>Quels sont les problèmes de ce texte ?</li><li>Réécrivez-le en cinq lignes au maximum pour un commandant de secteur, avec une version courte pour un exposé de 60 secondes.</li></ol>`,
answers:`<ol><li>Il n’y a ni source ni date ; la rumeur est présentée comme un fait ; capacité, intention et attribution sont confondues ; la certitude n’est pas justifiée ; l’attribution au gouvernement ne repose sur rien ; la recommandation est vague.</li><li><b>Modèle :</b> « <b>Rapporté :</b> le 3 mai, deux commerçants ont indiqué à une patrouille avoir vu un petit drone près de Tessa ; non corroboré. <b>Évaluation :</b> nous estimons avec un faible degré de confiance qu’un acteur inconnu observe la base. L’intention et l’identité sont inconnues. <b>Conséquence :</b> risque possible pour le personnel de la base. <b>Recommandation :</b> réexaminer la protection passive avec le commandant de la base ; transmettre à l’UNDSS aujourd’hui ; PIR soulevé à la prochaine réunion du MICM. » <b>60 secondes :</b> d’abord la conclusion principale, puis le degré de confiance, puis la décision requise.</li></ol>`},
{type:'CONSEIL DE PARTAGE',title:'Conseil de partage : l’armée du pays hôte veut le dossier',body:`<p><b>Durée :</b> 60 min · rôles : chef du JMAC, président du MICM, spécialiste des droits de l’homme, U2 de la force, conseiller juridique, point focal IM.</p><p>L’armée karanaise demande l’évaluation de la MINUKA sur un groupe armé, affirmant en avoir besoin « ce soir » pour protéger une ville. Sa 3e brigade est connue pour des exactions. Le produit s’appuie sur les rapports de deux villageois nommément désignés. Décidez.</p><ol><li>Qui décide, et en vertu de quelle délégation ?</li><li>Quelles vérifications passent en premier ? L’urgence les modifie-t-elle ?</li><li>Quelles conditions s’appliquent ?</li><li>Que peut-on partager, le cas échéant ?</li><li>Que faire si vous apprenez ensuite que le produit a servi à une opération abusive ?</li></ol>`,
answers:`<ol><li>Le Chef de mission, ou son délégué consigné. Pour le PKI stratégique, le délégué recommandé est le président du MICM. La délégation est consignée dans le MISP.</li><li>Une évaluation de l’entité aux fins du partage (Entity Assessment for Sharing), utilisant l’évaluation des risques de la HRDDP pour les forces de sécurité, et une évaluation des risques liés au partage (Sharing Risk Assessment) pour ce produit. La composante droits de l’homme se charge de la partie relative aux droits. L’urgence ne dispense pas de ces étapes (8.1.7), même si une menace contre des civils peut être traitée d’urgence et par d’autres moyens, tels qu’une alerte à la population ou la présence de la mission.</li><li>Conditions écrites : contrôle par l’émetteur ; utilisation limitée à la sûreté de l’ONU, à la connaissance de la situation et à la PoC ; aucune utilisation facilitant des violations ; maintien des marquages ; traitement équivalent.</li><li>Éventuellement une alerte expurgée, sans rien qui permette de remonter aux sources, aux témoins ou aux victimes. Ou rien du tout.</li><li>Le partage est suspendu en attendant l’enquête (8.1.10). Consignez-le au registre et informez la composante droits de l’homme.</li></ol>`},
{type:'CAS DE RÉCEPTION',title:'Le rapport du prisonnier : l’accepter ou non ?',body:`<p><b>Durée :</b> 45 min · équipe de la mission et observateur.</p><p>Un officier de sécurité karanais remet à la MINUKA un rapport « d’un prisonnier qui a parlé au bout de trois jours ». Il annonce une attaque contre un convoi de l’ONU vendredi. L’officier de liaison d’un État Membre ne propose rien qui le corrobore.</p><ol><li>Que devez-vous faire en premier ?</li><li>Pouvez-vous ignorer complètement l’alerte ?</li><li>Pouvez-vous annuler le convoi sur la seule base de ce rapport ?</li><li>Qui doit être informé ?</li></ol>`,
answers:`<ol><li>Réalisez une évaluation de l’entité aux fins de la réception (Entity Assessment for Receipt) et un examen préalable à la réception de renseignements (Intelligence Receipt Scan). S’il existe un risque réel que le rapport ait été obtenu sous la torture ou au moyen d’autres violations graves, la mission ne doit ni l’accepter ni le solliciter, et la composante droits de l’homme est informée immédiatement. Le Chef de mission devrait déjà avoir officiellement informé ses interlocuteurs de cette règle.</li><li>Les préoccupations de sécurité sont réelles et les renseignements sur une menace imminente sont traités en priorité, mais les étapes restent applicables. La mission peut renforcer son dispositif sur la base de sa propre évaluation indépendante et d’autres sources licites. Sollicitez des avis juridiques et en matière de droits de l’homme pour toute mesure de sécurité.</li><li>Les renseignements reçus ne doivent jamais constituer la seule source déterminante d’une action ou d’une décision de la mission. Cherchez d’abord d’autres informations licites.</li><li>Le commandant de la force ou le chef de la police, les points focaux IM et le DSS, ainsi que la composante droits de l’homme.</li></ol>`},
{type:'EXERCICE DE PROTECTION',title:'Rumeur à la radio : alerte, vérité et liberté d’expression',body:`<p><b>Durée :</b> 60 min · JMAC, information, droits de l’homme, affaires civiles, force.</p><p>Une station affirme que la MINUKA arme une communauté. Des messages haineux nomment des habitants d’Oru. En quelques jours, une foule se rassemble devant une entrée de l’ONU. Un commandant veut que la station soit fermée et que son personnel soit inscrit dans un dossier PKI.</p><ol><li>Cette question relève-t-elle du PKI ?</li><li>La mission peut-elle exiger la fermeture ?</li><li>Que contient le dossier au sujet des journalistes ?</li><li>Que faut-il signaler par ailleurs ?</li><li>Quelles mesures protègent la population cette semaine ?</li></ol>`,
answers:`<ol><li>Lorsque la mésinformation, la désinformation ou les discours de haine menacent la sûreté ou la PoC, ils entrent dans le processus des besoins et peuvent déclencher une acquisition par les entités PKI (Politique relative à l’intégrité de l’information, par. 38).</li><li>La fausseté ne suffit pas à justifier une limitation de l’expression, et les restrictions à la parole ne sont que rarement la bonne réponse. Privilégiez par défaut une information exacte. Toute mesure juridique relève des autorités compétentes, avec les conseils voulus.</li><li>Rien du seul fait qu’ils informent ou critiquent. Le principe d’un PKI respectueux des droits cite la vie privée, l’expression et l’association. Les données doivent être limitées aux besoins de sûreté et de sécurité, et le critère consistant à ne pas nuire s’applique.</li><li>L’incitation ou les violations passent par les canaux relatifs aux droits de l’homme : le signalement obligatoire est distinct du PKI.</li><li>Une information publique vérifiée, le dialogue avec la population, la présence, l’alerte rapide à la population en tenant compte de sa sécurité, et un examen des personnes que la foule pourrait prendre pour cible.</li></ol>`},
{type:'GROUPE DE POLICE',title:'Preuve ou renseignement ? Un groupe de discussion UNPOL',body:`<p><b>Durée :</b> 60 min · officier du renseignement en matière de criminalité d’UNPOL, police de l’État hôte, procureur, membre du MICM.</p><p>UNPOL conseille la police karanaise sur un programme ILP. Une analyse de la criminalité montre une hausse des vols de carburant liée à un réseau de commerçants. Un procureur demande les rapports bruts et l’identité d’un informateur. Le chef de la police demande à UNPOL de gérer ses informateurs.</p><ol><li>Distinguez le renseignement criminel, l’analyse de la criminalité et le renseignement en matière de criminalité.</li><li>À quoi sert le 5x5x5 ?</li><li>Les rapports bruts peuvent-ils être remis au procureur ?</li><li>UNPOL doit-il gérer les informateurs ?</li><li>Comment cela parvient-il au MICM ?</li></ol>`,
answers:`<ol><li>Le renseignement criminel concerne les auteurs d’infractions ; l’analyse de la criminalité concerne les infractions ; le renseignement en matière de criminalité fusionne les deux.</li><li>C’est le système d’UNPOL pour évaluer et traiter l’information, afin qu’un lecteur puisse juger de la fiabilité et des limites de traitement.</li><li>Le renseignement n’est pas une preuve. Toute communication exige une autorisation, une décision de partage et, le cas échéant, la HRDDP. La preuve obéit à ses propres règles, et les autorités compétentes décident de ce qui en constitue une. N’exposez jamais une personne à un préjudice.</li><li>Non. Arrêtez-vous et renvoyez. Le rôle d’UNPOL en matière d’ILP est principalement de renforcer les capacités ; les règles de la mission sur les sources humaines et son mandat s’appliquent. Les enfants ne doivent jamais être utilisés comme sources.</li><li>Par le groupe de répartition des tâches et de coordination (Tasking and Co-ordination Group), qui transmet les besoins au MICM et se réunit chaque trimestre.</li></ol>`},
{type:'DÉCISION FACE AUX COUPES',title:'Moins d’ISR, plus de drones : à quoi renoncer ?',body:`<p><b>Durée :</b> 75 min · groupe de planification du Chef de mission.</p><p>La MINUKA perd un quart de son personnel et un tiers de sa surveillance aérienne. Des postes d’assistants de liaison avec la population sont supprimés. Des drones ont été vus près de deux bases. Des fournisseurs proposent un outil d’IA pour classer les « menaces probables » à partir de publications publiques et de rapports de la mission.</p><ol><li>Quels besoins faut-il traiter en premier ?</li><li>Quel est le risque pour la protection de la perte du personnel de liaison ?</li><li>Quelles questions devez-vous poser au sujet de l’outil d’IA ?</li><li>Que dites-vous à votre personnel au sujet des drones ? Restez au niveau des politiques.</li><li>Quand faut-il fermer un site ?</li></ol>`,
answers:`<ol><li>Classez les besoins selon leur valeur pour la décision : sûreté du personnel, menaces imminentes pour la PoC, puis questions à plus long terme. Abandonnez ce qu’aucun responsable n’utilise. Consignez ce à quoi vous ne pouvez plus répondre et indiquez-le dans les produits.</li><li>L’IPI indique que leur perte a nui à l’alerte rapide en 2025–26. L’alerte repose sur la confiance. Les femmes et les communautés isolées risquent d’être moins entendues.</li><li>Fondement licite dans le MISP ; destination et propriété des données ; vie privée et principe consistant à ne pas nuire ; explicabilité des résultats ; biais ; jugement humain sur chaque évaluation ; règles juridiques, relatives aux droits de l’homme et aux technologies de l’ONU. Un classement n’est pas une évaluation.</li><li>L’ONU dispose de Directives C-UAS et d’orientations de l’OMA sur la protection passive, présentées comme un travail en cours. Renvoyez aux ordres en vigueur de la mission. Un cours public ne traite pas des méthodes de neutralisation.</li><li>C’est une décision des responsables. L’UNISFA a évacué et fermé Kadugli après l’attaque de décembre 2025, puis fermé deux bases d’opérations en raison de la menace des UAV. Le PKI éclaire la décision ; il ne la prend pas.</li></ol>`}
];
TRACK.flash=[
['Objet du PKI','Des décisions qui améliorent la connaissance de la situation ainsi que la sûreté et la sécurité du personnel de l’ONU, et qui éclairent la PoC (Politique, par. 5).'],['Absence de définition','La Politique de 2019 ne contient aucune définition autonome du renseignement aux fins du maintien de la paix.'],['Information et évaluation','L’information rend compte d’événements ; le PKI est une évaluation issue de son analyse.'],['Statut de la Politique','Réf. 2019.08, dernière version trouvée ; date de réexamen dépassée en 2021. Vérifiez les orientations actuelles de l’ONU.'],['Parcours vers la politique','Brahimi 2000, résolution 1894 (2009), HIPPO 2015, résolution 2295 (2016), politiques de 2017 et 2019.'],
['Sept principes','Respect des règles ; caractère non clandestin ; domaines d’application ; souveraineté des États ; indépendance ; responsabilité, capacité et autorité ; sécurité et confidentialité.'],['Non clandestin','Une acquisition conçue pour garantir le secret ou la dissimulation sort du cadre du PKI.'],['Indépendance','Pleinement autonome par rapport à tout système national de renseignement ; caractère exclusivement international.'],['Domaines d’application','Connaissance de la situation, sûreté et sécurité du personnel de l’ONU, et tâches de PoC.'],
['MICM','Dirige et supervise le cycle ; ne procède pas à l’analyse ; présidence civile, de préférence le chef de cabinet.'],['JMAC','Analyse intégrée à moyen et long terme pour les responsables ; dirige la rédaction du MIAP et du MISP.'],['JOC','Connaissance intégrée de la situation, rapports et appui en cas de crise, 24 heures sur 24.'],['U2, G2, S2, COIST','Quartier général de la force, secteur, bataillon ; le COIST est une équipe de compagnie facultative de deux personnes.'],['PICT','Coordonnateur du PKI au Siège et contact pour le renseignement fourni volontairement par les États Membres.'],
['Cycle en cinq étapes','Direction ; Acquisition ; Examen et collationnement ; Analyse ; Diffusion.'],['CCIR, PIR, RFI','Besoins critiques du commandant ; besoins prioritaires ; demande précise d’information.'],['MIAP et MISP','Plan d’acquisition ; plan d’appui fixant les limites, les méthodes acceptables et inacceptables, et le partage.'],['PKIMB','Conseil de gestion du PKI : valide les priorités ; seul ou au sein du MICM.'],
['Catégories HPKI','Fortuit non dirigé (pas de HPKI) ; dirigé sans incitation (méthode de base) ; dirigé avec incitation ; clandestin (ces deux derniers strictement interdits).'],['Enfants','Ne doivent pas être utilisés comme sources : ils ne peuvent pas donner un consentement libre et éclairé.'],['OPKI d’abord','L’information accessible au public est la première méthode à envisager, mais elle doit quand même être validée.'],['Faux comptes','Interdits, et l’emploi à l’ONU ne doit pas être dissimulé lors d’échanges en ligne.'],['Ligne rouge du TPKI','Pas de ciblage cinétique de personnes ou de groupes, sauf mandat explicite visant à atténuer les dommages causés aux civils.'],
['ACH','Analyse des hypothèses concurrentes : confronter les éléments à plusieurs explications et tenter de les réfuter.'],['AOE','Analyse de l’environnement opérationnel, enseignée en trois phases.'],['Perspective de genre','Demandez qui est entendu, qui est en danger et quels rapports sont minimisés.'],['Cotation','La fiabilité de la source et la crédibilité de l’information sont évaluées séparément.'],
['PIE et SPIE','Estimation de renseignement aux fins du maintien de la paix et sa version courte.'],['INTREP et INTSUM','Rapport sur un événement précis ; synthèse périodique.'],['Conclusion d’abord','Énoncez le jugement, le degré de confiance et la décision requise, puis les détails.'],
['ST/SGB/2007/6','Règles de l’ONU sur la classification et le traitement des informations sensibles ; les données PKI appartiennent à l’Organisation.'],['Partage hors de la mission','Chef de mission ou délégué ; conditions écrites ; évaluation de l’entité et évaluation des risques liés au partage ; HRDDP.'],['Ligne rouge de la torture','En cas de risque réel, la mission ne doit ni accepter ni solliciter ; informez la composante droits de l’homme.'],['Limite de la source unique','Les renseignements reçus ne doivent jamais constituer la seule source déterminante d’une action de la mission.'],['Urgence','Ne dispense pas des étapes de partage ou de réception.'],
['Règle de l’UNDSS','L’information touchant la sûreté du personnel est transmise en temps utile au plus haut représentant de l’UNDSS (11.3.2).'],['Politique relative à l’intégrité de l’information','Réf. 2024.15 : mésinformation, désinformation, discours de haine ; la fausseté ne suffit pas à justifier une limitation de l’expression.'],['Signalement obligatoire','Les violations relevées dans le cycle, telles que les violences sexuelles liées aux conflits et les violations graves contre des enfants, passent par les canaux appropriés.'],
['Renseignement en matière de criminalité','Fusionne le renseignement criminel (auteurs) et l’analyse de la criminalité (infractions).'],['5x5x5','Système d’UNPOL pour évaluer et traiter l’information.'],['TCG','Tasking and Co-ordination Group : transmet les besoins de la police au MICM ; se réunit chaque trimestre.'],
['Kadugli, 13 déc. 2025','Six soldats de la paix bangladais tués et au moins huit blessés ; aucune conclusion sur la responsabilité n’a été vue.'],['ASIFU','Ancienne unité de fusion de la MINUSMA ; pas une structure type actuelle.'],['C-UAS au niveau des politiques','Directives publiées, avec des orientations sur la protection passive ; le C-34 encourage l’établissement d’un cadre.'],['Limite de l’enseignement','Enseignez les règles, les limites, l’analyse et l’éthique ; refusez les savoir-faire opérationnels et les techniques.']
];
TRACK.exam=[
{q:'Outre les membres principaux, qui peut être invité au MICM ?',o:['Les spécialistes des affaires politiques, juridiques et des droits de l’homme','Des représentants des groupes armés analysés dans la zone','Des officiers de renseignement de l’État hôte, comme membres permanents votants','Des journalistes couvrant la mission, dans le cadre d’un accord de presse'],a:0,e:'Politique, par. 12.'},
{q:'Le PKI opérationnel ou tactique destiné à un bureau de l’ONU extérieur à la mission est adressé :',o:['À son point focal de sécurité le moins élevé en grade, pour classement dans ce bureau','À tout membre du personnel qui en fait la demande par écrit','Au comité du Conseil de sécurité chargé du pays','Au plus haut responsable du DSS et au responsable désigné'],a:3,e:'Directives sur le partage, p. 8 et 9.'},
{q:'Le respect des Directives TPKI est décrit comme :',o:['Facultatif, sauf si un commandant de la force l’ordonne pour un secteur','Contraignant pour les États Membres au titre du Chapitre VII de la Charte','Vivement recommandé','Obligatoire sous peine de rapatriement du contingent'],a:2,e:'TPKI, p. 3 et 4. Les Directives HPKI, OPKI et sur le partage parlent d’obligation.'},{q:'Que dit la Politique PKI de 2019 quant à la définition du renseignement aux fins du maintien de la paix ?',o:['Elle adopte la définition de l’OTAN avec quelques modifications','Elle ne contient aucune définition autonome','Elle définit le PKI comme toute information détenue par une mission','Elle laisse la définition à chaque Chef de mission'],a:1,e:'Sa section Termes définit uniquement des mots connexes ; enseignez l’objet énoncé au par. 5.'},
{q:'Pourquoi le mot renseignement a-t-il longtemps été sensible à l’ONU ?',o:['Les États craignaient d’être espionnés','La Charte interdit expressément ce mot dans tous les documents de l’ONU','La CIJ a déconseillé son emploi dans le maintien de la paix','Les pays fournisseurs de contingents n’avaient pas de personnel de renseignement'],a:0,e:'La souveraineté et la crainte d’abus ont motivé cette prudence.'},
{q:'Quel rapport de 2000 a proposé un organe d’analyse stratégique au Siège ?',o:['Le rapport HIPPO','Le rapport Santos Cruz','Le rapport Carlsson sur le Rwanda','Le rapport Brahimi'],a:3,e:'A/55/305 ; cet organe s’est heurté à une résistance politique.'},
{q:'Quelle affirmation distingue le mieux l’information du PKI ?',o:['L’information est secrète et le PKI est public','L’information vient de la force et le PKI des civils','L’information rend compte d’événements ; le PKI est une évaluation','L’information est écrite et le PKI est oral'],a:2,e:'Manuel militaire du PKI (2025).'},
{q:'Comment un formateur doit-il décrire le statut actuel de la Politique de 2019 ?',o:['Remplacée en 2025 par le Manuel militaire, qui régit désormais toutes les composantes','Dernière version trouvée ; vérifier les orientations actuelles','Annulée lorsque sa date de réexamen est passée en mai 2021','Applicable uniquement aux missions créées après 2019'],a:1,e:'Sa date de réexamen est dépassée et aucune nouvelle publication n’a été trouvée.'},
{q:'La Politique s’applique :',o:['À tous les rapports sensibles d’une mission, y compris les rapports courants','À tout courriel envoyé par le personnel de l’ONU dans une zone de mission','Aux seuls rapports de la force, le JMAC suivant ses propres règles','Aux éléments gérés dans le cycle du PKI'],a:3,e:'Par. 8 : les rapports courants sont distincts, même lorsqu’ils sont sensibles.'},
{q:'Le principal client du PKI dans une mission est :',o:['Le Chef de mission','Le ministre de la défense de l’État hôte','Le principal pays fournisseur de contingents','Chaque commandant de secteur agissant seul'],a:0,e:'Le Chef de mission donne l’orientation stratégique et est le client principal.'},
{q:'Le principe du caractère non clandestin exclut une acquisition :',o:['Dirigée par un besoin émanant du MICM','Effectuée par du personnel militaire en patrouille','Conçue pour garantir le secret ou la dissimulation','Marquée ultérieurement Strictement confidentiel'],a:2,e:'Une telle activité sort du cadre du PKI.'},
{q:'Lequel de ces éléments n’est PAS un domaine d’application de la Politique ?',o:['La connaissance de la situation','La sûreté et la sécurité de tout le personnel de l’ONU dans la zone de la mission','Les tâches de protection des civils','L’appui aux raids antiterroristes de l’État hôte'],a:3,e:'Les limites d’objet font partie des principes.'},
{q:'Le principe d’indépendance signifie que le système de la mission est :',o:['Exempt de contrôle de l’ONU, y compris de l’OIOS','Dispensé des règles de la Charte','Géré séparément du Chef de mission','Autonome par rapport aux systèmes nationaux de renseignement'],a:3,e:'Il a un caractère exclusivement international.'},
{q:'Le respect de la souveraineté des États dans la Politique englobe :',o:['Les États hôtes et voisins','L’État hôte uniquement','Les membres permanents du Conseil uniquement','Les pays fournisseurs de contingents uniquement'],a:0,e:'Le PKI ne doit pas être utilisé contre eux ni pour les menacer.'},
{q:'Qui répond du système PKI dans une mission ?',o:['Le chef du JMAC, en dernier ressort devant le MICM','Le commandant de la force, devant les États contributeurs','Le Chef de mission','L’analyste de chaque entité'],a:2,e:'Le Chef de mission répond en dernier ressort devant le Secrétaire général.'},
{q:'Un collègue estime qu’un petit risque pour un contact est acceptable si le rapport a de la valeur. Les règles disent :',o:['Accepter le risque si le commandant s’y engage d’abord par écrit','Agir si le contact donne son accord oral','L’accepter uniquement en cas d’urgence de PoC','Veiller particulièrement à ne pas exposer les sources à un préjudice'],a:3,e:'Premier principe ; Manuel PKISR : la sécurité de la source est primordiale.'},
{q:'Face à une proposition clandestine, la première démarche correcte consiste à :',o:['Mener un petit projet pilote et en communiquer les résultats au MICM','Modifier la formulation de la proposition dans le plan','Demander à un officier de liaison national de l’exécuter à votre place','S’arrêter et renvoyer la question'],a:3,e:'La réponse n’est jamais une façon plus habile de procéder.'},
{q:'Que fait le MICM ?',o:['Il rédige les estimations de la mission','Il enquête sur les fautes','Il dirige et supervise le cycle','Il commande les unités de la force'],a:2,e:'Par. 12.3 : il ne procède pas à l’analyse.'},
{q:'Le président du MICM est :',o:['Un civil, de préférence le chef de cabinet','Le commandant de la force dans toutes les missions','Le plus haut responsable de l’UNDSS','Toujours le chef de la police'],a:0,e:'Désigné par le Chef de mission (15.1) ; le chef du JMAC si le JMAC assume cette fonction.'},
{q:'Quelle association est correcte ?',o:['JOC : analyse à long terme ; JMAC : veille 24 heures sur 24, dans chaque mission et secteur','JMAC : uniquement les tâches de la force ; JOC : uniquement les tâches de la police','JMAC et JOC : tous deux remplacés par le U2 en 2025','JMAC : analyse à moyen et long terme ; JOC : connaissance de la situation'],a:3,e:'Manuel militaire du PKI, p. 76 et 77.'},
{q:'Le personnel PKI du quartier général de la force, du secteur et du bataillon est, dans l’ordre :',o:['S2, G2, U2','U2, S2, G2','G2, U2, S2','U2, G2, S2'],a:3,e:'Le COIST est une équipe de compagnie facultative de deux personnes.'},
{q:'Qui reçoit l’information touchant la sûreté du personnel de l’ONU ?',o:['Le plus haut représentant de l’UNDSS','L’ambassade la plus proche','Le chef de la police de l’État hôte','Uniquement le commandant de l’émetteur'],a:0,e:'Politique, 11.3.2, en temps utile.'},
{q:'Au Siège, quel bureau appuie les JMAC ?',o:['OMA','La Division de la police','OIOS','UNOCC'],a:3,e:'L’OMA appuie les U2, et la Division de la police appuie la police.'},
{q:'Selon les documents, le plan d’appui est appelé PKISP ou MISP. Un officier rigoureux :',o:['Les traite comme deux plans distincts, chacun devant être approuvé par le chef de cabinet','Utilise le terme du document en vigueur et signale la variation','Signale une erreur au Conseil','Ignore celui qui est paru en premier'],a:1,e:'L’annexe C de la Politique dit PKISP ; les orientations ultérieures disent MISP.'},
{q:'Les cinq étapes du cycle sont :',o:['Planifier, collecter, traiter, présenter, archiver','Direction, acquisition, analyse, partage','Répartition des tâches, espionnage, tri, rapport, examen','Direction, acquisition, examen et collationnement, analyse, diffusion'],a:3,e:'Politique, par. 10. Les quatre étapes du Manuel de 2019 sont dépassées.'},
{q:'Les besoins d’information sont généralement :',o:['Formulés sous forme de questions','Rédigés sous forme d’ordres quotidiens','Tenus secrets vis-à-vis des analystes','Fixés par les États contributeurs'],a:0,e:'Politique, 12.9 ; réexaminés au moins une fois par an.'},
{q:'Qui dirige la rédaction du MIAP et du MISP ?',o:['L’état-major particulier du commandant de la force','OIOS, avec le conseiller juridique','Le JMAC','Le comité du Conseil de sécurité'],a:2,e:'Le Mécanisme les valide (12.6).'},
{q:'Le plan d’appui doit énumérer :',o:['Les noms de tous les contacts et informateurs','Les notes personnelles de chaque analyste','Les fonds classifiés de l’État hôte','Les méthodes acceptables et inacceptables'],a:3,e:'Ainsi que les considérations relatives aux droits de l’homme et au droit, la sécurité et le partage.'},
{q:'Le conseil de gestion du PKI :',o:['Valide les priorités','Juge le personnel pour des fuites','Remplace le Chef de mission','Vérifie les finances de l’ONU'],a:0,e:'Manuel PKISR, p. 23 ; seul ou au sein du MICM.'},
{q:'Un G2 de secteur a besoin d’une précision détenue par le JMAC. L’outil habituel est :',o:['Un CCIR','Un INTSUM','Un RFI','Un SOFA'],a:2,e:'Une demande d’information (Request for Information).'},
{q:'Quelle question constitue le meilleur PIR ?',o:['Dites-moi tout sur les groupes armés de toute la région','La situation de sécurité est-elle bonne ou mauvaise en ce moment ?','Veuillez envoyer tous les rapports dont vous disposez ce mois-ci','Quel groupe a l’intention de marcher sur Oru, et quand ?'],a:3,e:'Elle est ciblée et liée à une décision.'},
{q:'Le plan du G2 doit suivre :',o:['Les préférences de chaque bataillon','Le plan national de l’État contributeur','La liste de collecte d’un organisme partenaire','Le plan ISP de la force, conforme au MISP'],a:3,e:'Manuel militaire du PKI, p. 79.'},
{q:'Quelle catégorie de sources humaines constitue la méthode de base du PKI ?',o:['Dirigée et sans incitation','Dirigée, avec incitation mais ouverte','Dirigée et clandestine','Non dirigée et avec incitation'],a:0,e:'Directives HPKI, p. 5. Le contact fortuit ne relève pas du HPKI.'},
{q:'Verser de l’argent ou offrir des cadeaux en échange d’informations est :',o:['Autorisé en deçà d’un plafond local','Autorisé si c’est consigné et approuvé par le chef','Interdit par les Directives HPKI','Laissé à l’appréciation du contingent'],a:2,e:'HPKI 12.14. Citez les Directives pour cette interdiction.'},
{q:'Le HPKI doit être utilisé :',o:['Après que les autres moyens se sont révélés impossibles ou non concluants','Avant toute autre méthode','Uniquement au quartier général de la force','Chaque fois qu’un commandant, à tout niveau, souhaite l’utiliser pour aller vite'],a:0,e:'HPKI 12.1. Il n’est pas obligatoire pour les entités de base.'},
{q:'Un garçon de 14 ans propose de fournir des informations sur un groupe. Vous :',o:['Acceptez si un parent donne son consentement écrit à la mission','Acceptez uniquement pour la protection des civils','Le gardez comme contact officieux dans le dossier','Ne l’utilisez pas ; renvoyez les préoccupations de protection'],a:3,e:'Les enfants ne doivent pas être utilisés comme sources HPKI.'},
{q:'Un officier de mission peut-il dissimuler son emploi à l’ONU dans ses échanges avec un contact ?',o:['Non','Oui, en cas de menace','Oui, si le MICM est d’accord','Oui, en civil'],a:0,e:'HPKI 12.5 ; Manuel PKISR, p. 33.'},
{q:'Quelle est la première méthode à envisager selon les Directives OPKI ?',o:['Les sources humaines','L’information accessible au public','Les capteurs techniques','Les rapports de partenaires'],a:1,e:'Faible risque, faible coût et rapidité ; elle doit quand même être validée.'},
{q:'Les faux comptes aux fins de l’OPKI sont :',o:['Autorisés pour les analystes du JMAC','Autorisés lorsqu’une menace est imminente','Autorisés s’ils sont supprimés dans la semaine','Interdits'],a:3,e:'OPKI 11.8.'},
{q:'Les éléments obtenus sur du matériel personnel :',o:['Peuvent être utilisés après examen','Sont la propriété de l’analyste','Sont préférés pour leur rapidité','Ne doivent pas être utilisés pour le PKI'],a:3,e:'OPKI, p. 7 et 8.'},
{q:'Avant d’affecter un moyen aérien PKISR, les planificateurs doivent prendre en considération :',o:['L’autorisation de l’État hôte','Le drapeau national du contingent','Le plan de presse de la mission','Uniquement la météo et la portée'],a:0,e:'Manuel PKISR, p. 28 ; A/80/19, par. 104, mentionne l’autorisation et l’approbation.'},
{q:'Le TPKI porte principalement sur :',o:['La sécurité des courriels du personnel','Les engins explosifs improvisés et les éléments connexes liés à la menace','Les procès-verbaux d’entretien et les dossiers personnels des détenus','Les audits financiers'],a:1,e:'Directives TPKI, p. 3 ; les lieux où se trouvent des explosifs relèvent d’abord de l’EOD.'},
{q:'L’examen et le collationnement consistent à :',o:['Informer immédiatement le Chef de mission de chaque nouveau rapport parvenant au JMAC','Trier, vérifier et consigner les éléments en vue de l’analyse','Détruire les doublons et les rumeurs','Confier des tâches à de nouvelles sources'],a:1,e:'Cette étape précède l’analyse.'},
{q:'La cotation porte séparément sur :',o:['Le grade de l’analyste et la taille de l’unité','La longueur du rapport et sa langue','La fiabilité de la source et la crédibilité de l’information','Le marquage de sécurité du produit et sa date de communication aux lecteurs'],a:2,e:'Manuel, p. 34 à 37.'},
{q:'Deux rapports concordent. Vous devez d’abord vous demander :',o:['Quelle unité s’attribuera le mérite de la concordance','S’ils ont une seule et même origine','Dans quel délai le texte peut être publié','S’il faut doubler le degré de confiance'],a:1,e:'La fausse corroboration est un piège courant.'},
{q:'L’ACH fonctionne le mieux lorsque vous :',o:['Choisissez tôt votre explication préférée','Essayez de réfuter chaque hypothèse','Comptez ceux qui sont d’accord avec vous','Évitez les avis divergents'],a:1,e:'Manuel, p. 41 à 43.'},
{q:'Un élément compatible avec toutes les hypothèses est :',o:['L’élément le plus solide que l’on puisse avoir','Peu utile pour choisir entre elles','La preuve qu’elles sont toutes vraies','Un motif de clore l’évaluation'],a:1,e:'Cherchez ce qui permet de les départager.'},
{q:'Une chronologie ou une représentation de schémas sert principalement à :',o:['Prouver qui est coupable','Remplacer les rapports de terrain','Révéler des séquences et des schémas','Fixer les priorités budgétaires'],a:2,e:'Un schéma est un indicateur, pas une conclusion.'},
{q:'Accepter la première explication et ne chercher que ce qui l’étaye relève :',o:['De l’effet miroir','D’une saine priorisation','Du biais de confirmation','De l’expurgation'],a:2,e:'Les méthodes structurées aident à le réduire.'},
{q:'Une perspective de genre dans l’analyse pose la question suivante :',o:['Combien de femmes servent dans les unités du JMAC de tous les secteurs','Quelles voix et quels risques manquent au tableau','Quel sexe fait le meilleur analyste en général','Si les hommes doivent être exclus des rapports'],a:1,e:'L’IPI (2020) a relevé la perspective de genre comme un point faible.'},
{q:'Quel produit est une estimation courte ?',o:['SPIE','INTREP','RFI','MISP'],a:0,e:'Manuel, p. 70.'},
{q:'Un INTREP est généralement :',o:['Un document de stratégie annuel','Un rapport sur un événement précis','Un plan d’acquisition de données','Une liste de contacts'],a:1,e:'Manuel, p. 75 et annexes.'},
{q:'La règle du Manuel pour les produits est de :',o:['Maintenir une nette distinction entre information et évaluation','Cacher toute incertitude aux responsables','Rédiger la version la plus détaillée possible chaque fois qu’elle est lue','Inclure les noms bruts des sources pour plus de crédibilité'],a:0,e:'Manuel, p. 75.'},
{q:'Quelle formulation d’évaluation est appropriée ?',o:['Tout le monde sait qu’ils attaqueront vendredi','La source annonce une attaque, donc c’est certain','Nous estimons avec un faible degré de confiance qu’une attaque est possible','L’ennemi est manifestement mauvais et doit être arrêté par tous les moyens dont dispose la mission'],a:2,e:'Énoncez le jugement et le degré de confiance.'},
{q:'Dans un exposé d’une minute, commencez par :',o:['L’historique du conflit','La liste de toutes les sources consultées','La conclusion principale et la décision requise','Vos opinions personnelles sur le mandat'],a:2,e:'Les détails suivent sur demande.'},
{q:'Une estimation parfaite arrive après la décision. Sa valeur est :',o:['Inchangée','La plus élevée de toutes','Faible pour cette décision','Un motif de médaille'],a:2,e:'Le respect des délais fait partie de la qualité.'},
{q:'Un produit court et honnête comportant des lacunes vaut mieux qu’un produit complet mais tardif lorsque :',o:['L’auteur souhaite partir en congé','La décision ne peut pas attendre','Le lecteur n’aime pas les textes longs','Les sources l’ont demandé'],a:1,e:'Indiquez clairement les lacunes.'},
{q:'Un rapport thématique convient à :',o:['L’unique incident de ce soir','Une question durable nécessitant un traitement approfondi','La demande d’une précision','Un journal personnel des événements tenu par l’officier de service cette nuit-là'],a:1,e:'Annexes du Manuel.'},
{q:'La règle par défaut pour le PKI au sein de la mission est :',o:['Le partage, les marquages plus élevés étant exceptionnels','Strictement confidentiel pour tous les produits','Aucune circulation sans l’approbation du Conseil','Le partage uniquement avec les États contributeurs'],a:0,e:'Politique, 11.2.1.'},
{q:'Les données PKI sont la propriété :',o:['De l’auteur','De l’État contributeur','De l’Organisation','De l’État hôte'],a:2,e:'Politique, par. 11 ; ST/SGB/2007/6 s’applique.'},
{q:'Qui décide du partage hors de la mission ?',o:['Tout analyste qui détient le produit et connaît le lecteur','Le Chef de mission ou son délégué désigné par écrit','L’officier de liaison du pays fournisseur de contingents dans la mission','Le ministère de l’État hôte qui l’a demandé'],a:1,e:'Politique, 11.4.1.'},
{q:'Avant tout partage avec une entité extérieure à l’ONU, la mission a besoin :',o:['Uniquement d’une promesse orale de l’officier demandeur','D’un vote des membres du Conseil de sécurité','D’une évaluation de l’entité et d’une évaluation des risques liés au partage','Uniquement de la signature du U2 sur la page de garde du produit transmis'],a:2,e:'Directives sur le partage, p. 5 à 8 ; HRDDP pour les forces de sécurité.'},
{q:'Une menace est imminente et un partenaire demande le produit immédiatement. Les étapes sont :',o:['Suspendues pendant 24 heures','Levées par l’officier présent le plus élevé en grade','Remplacées par un appel téléphonique','Maintenues malgré l’urgence'],a:3,e:'Directives sur le partage, 8.1.7.'},
{q:'Lorsqu’un produit peut parvenir directement ou indirectement à des forces de sécurité extérieures à l’ONU :',o:['La HRDDP s’applique','La HRDDP ne s’applique jamais à l’information','Seul OIOS décide','Aucune trace n’est conservée'],a:0,e:'Politique, 11.4.4.'},
{q:'Lorsque des renseignements reçus peuvent provenir de la torture, la mission :',o:['Peut les utiliser s’ils semblent exacts','Ne doit ni les accepter ni les solliciter','Peut les accepter pour la protection des civils','Peut les accepter s’ils sont expurgés'],a:1,e:'Directives sur le partage, 9.9. La composante droits de l’homme est informée immédiatement.'},
{q:'Fonder une action de la mission uniquement sur des renseignements reçus est :',o:['Autorisé pour les menaces imminentes uniquement','Autorisé si le partenaire est digne de confiance','Jamais autorisé','Autorisé avec une annexe'],a:2,e:'Directives sur le partage, p. 12.'},
{q:'Si un partenaire enfreint les conditions, ou est fortement soupçonné de le faire :',o:['Envoyer un rappel à la prochaine réunion','Le partage est suspendu en attendant l’enquête','Abaisser le marquage des produits futurs','Poursuivre, mais expurger tous les nouveaux produits'],a:1,e:'Directives sur le partage, 8.1.10.'},
{q:'L’expurgation consiste à :',o:['Supprimer le registre au bout d’un an','Réécrire l’évaluation pour plaire à un partenaire','Retirer les détails pouvant exposer une source, un témoin ou une victime','Traduire le produit dans la langue de l’État hôte pour ses ministères et sa presse'],a:2,e:'Directives sur le partage, p. 4.'},
{q:'Le registre et la matrice d’accès existent pour que :',o:['Les médias puissent lire les dossiers','Le traitement puisse être retracé','Les analystes puissent se dispenser du marquage','Les sources puissent être rémunérées'],a:1,e:'Politique, 11.3.3 et 12.10 ; ouverts au contrôle.'},
{q:'Dans l’alerte rapide, le PKI sert la mission en :',o:['Repérant les menaces imminentes à temps pour agir','Prédisant chaque attaque avec certitude','Remplaçant le dialogue avec la population','Levant la responsabilité de l’État hôte'],a:0,e:'Politique, par. 5 ; l’analyse du JMAC a éclairé les décisions de l’UNMISS (A4P, 2026).'},
{q:'Une rumeur radio est fausse, mais ne constitue pas encore un risque pour la sûreté. Selon la Politique relative à l’intégrité de l’information :',o:['La fausseté ne suffit pas à justifier une limitation de l’expression','La station doit être fermée immédiatement','Les journalistes sont inscrits dans le dossier PKI','La mission doit faire cesser la diffusion sans délai et le signaler'],a:0,e:'Les restrictions à la parole ne sont que rarement la bonne réponse.'},
{q:'La mésinformation devient une question de PKI lorsqu’elle :',o:['Critique la mission','Est publiée dans une langue étrangère','Émane d’un responsable politique','Menace la sûreté ou la PoC'],a:3,e:'Politique relative à l’intégrité de l’information, par. 38.'},
{q:'Un analyste découvre des éléments de violences sexuelles liées aux conflits. Ils doivent :',o:['Rester uniquement dans le dossier PKI','Attendre le réexamen annuel','Passer par les canaux de signalement obligatoire','Être communiqués à l’unité mise en cause pour que son commandant puisse y répondre'],a:2,e:'Manuel, p. 15.'},
{q:'Des coupes budgétaires ont supprimé les assistants de liaison. Un effet probable est :',o:['Une alerte rapide affaiblie','Moins de demandes de protection de la part des civils','Moins de règles relatives aux droits de l’homme','Un meilleur accès aux villages isolés'],a:0,e:'Rapport d’atelier de l’IPI (2026).'},
{q:'Alerter une communauté d’une menace exige de la prudence parce que :',o:['La Charte interdit les alertes','Cela pourrait exposer les personnes ayant fourni des informations','Les civils n’ont pas le droit de connaître les menaces','Seul le Conseil peut alerter les civils'],a:1,e:'Ne pas nuire ; expurger.'},
{q:'Le renseignement en matière de criminalité, dans le Manuel ILP, est :',o:['Uniquement l’information sur les auteurs, recueillie par des enquêteurs pour servir au procès','Une preuve destinée au tribunal','Uniquement une carte de la criminalité','Une fusion du renseignement criminel et de l’analyse de la criminalité'],a:3,e:'Manuel ILP, p. 7.'},
{q:'Le rôle d’UNPOL en matière d’ILP est principalement de :',o:['Remplacer partout la police de l’État hôte','Gérer le PKI militaire de la mission','Renforcer les capacités de la police de l’État hôte','Conseiller la CPI sur le droit de la preuve'],a:2,e:'Manuel ILP, p. 2 et 3 ; UNPOL l’applique aussi lorsque le mandat le prévoit.'},
{q:'Le 5x5x5 est :',o:['Un système d’évaluation et de traitement de l’information','Une règle de dotation en effectifs de la mission','Une formation de patrouille','Une procédure judiciaire d’admission des rapports de police comme preuves au procès'],a:0,e:'Manuel ILP, p. 14 et 15.'},
{q:'Le groupe de répartition des tâches et de coordination est relié :',o:['Au Conseil de sécurité','Au MICM','Au Tribunal du contentieux administratif','Au Comité d’état-major'],a:1,e:'Manuel ILP, p. 31 : il se réunit chaque trimestre.'},
{q:'Un procureur demande un rapport PKI brut comme preuve. Votre premier réflexe est :',o:['L’envoyer, car la justice est un objectif de l’ONU','Refuser définitivement et ne consigner la demande nulle part dans la mission','Le renseignement n’est pas une preuve ; renvoyer la décision de partage','Demander à la source de témoigner immédiatement'],a:2,e:'Les autorités compétentes décident en matière de preuve ; les règles de partage restent applicables.'},
{q:'Un chef de police de l’État hôte demande à UNPOL de gérer ses informateurs. Vous :',o:['Acceptez s’il signe un mémorandum pour le dossier','Acceptez uniquement pour les infractions graves','Acceptez et partagez les honoraires avec lui','Vous arrêtez et renvoyez la question'],a:3,e:'La bonne réponse à une demande qui franchit la ligne.'},
{q:'Quelle est la façon la plus sûre de décrire l’attaque de Kadugli de décembre 2025 ?',o:['Énoncer les faits sans attribuer la responsabilité','Nommer le groupe désigné par le gouvernement hôte','Nommer le groupe le plus probable selon votre lecture de la presse','Dire que personne n’a été blessé'],a:0,e:'Six morts et au moins huit blessés ; aucune conclusion n’a été trouvée.'},
{q:'Après Kadugli, l’UNISFA :',o:['A agrandi la base logistique','A fermé la base, puis deux bases d’opérations','A transféré son quartier général à New York','A mis fin à son mandat de sa propre initiative'],a:1,e:'Security Council Report, mai 2026.'},
{q:'À quel niveau un cours public doit-il aborder la lutte contre les drones ?',o:['Les méthodes précises de neutralisation','Les faiblesses de systèmes particuliers','Les politiques, les règles et la sensibilisation à la protection passive','La réparation sur le terrain du matériel de protection par le personnel de l’unité pendant l’attaque'],a:2,e:'Limite absolue de l’enseignement ; renvoyez aux ordres en vigueur de la mission.'},
{q:'Selon les Directives TPKI, l’ONU n’utilise pas le TPKI pour :',o:['Partager des analyses avec le JMAC','Consigner des preuves d’attaques contre des soldats de la paix en vue de poursuites par les autorités compétentes','Tirer des enseignements sur les menaces liées aux engins explosifs improvisés','Appuyer un ciblage cinétique, sauf mandat explicite'],a:3,e:'TPKI, par. 10, et uniquement pour atténuer les dommages causés aux civils.'},
{q:'Un outil d’IA classe des personnes comme menaces probables. La bonne attitude est de :',o:['Vérifier d’abord le droit, les données, les biais et le jugement humain','Lui faire confiance, puisque les machines n’ont pas de biais','L’utiliser, puis n’informer le MICM que s’il classe mal les personnes','Éviter d’en informer la composante droits de l’homme'],a:0,e:'Un classement n’est pas une évaluation ; les règles relatives aux droits et à la vie privée restent applicables.'},
{q:'L’ASIFU doit être enseignée comme :',o:['L’unité type actuelle de l’ONU','Une ancienne pratique de la MINUSMA','Une unité figurant dans le Manuel de 2025','Un bureau de l’UNDSS'],a:1,e:'La MINUSMA a fermé le 31 décembre 2023.'},
{q:'En citant en 2026 un document d’orientation de 2019, un formateur doit :',o:['Dire qu’il est certainement en vigueur, sans vérifier son statut','Retirer la date pour éviter toute objection','Donner la référence et la date, et inviter à vérifier les orientations actuelles','Copier de longs extraits pour être exact'],a:2,e:'Le Manuel limite également la reproduction.'},
{q:'Un apprenant demande comment gérer une source sans être détecté. Vous :',o:['Répondez pendant une pause, à l’écart du groupe','Déclinez, expliquez la limite et revenez à la règle','Le renvoyez à un forum en ligne sur le sujet','Ne donnez que des conseils généraux tirés de votre carrière de militaire sur le terrain'],a:1,e:'Le caractère non clandestin est lui-même la leçon.'},
{q:'Le rapport Santos Cruz doit être cité :',o:['Avec une cote S/2018/1, puisque tous les rapports en ont une','Par son titre et sa date, sans cote S','Comme une résolution du Conseil de sécurité','Comme un document de politique contraignant du DPO'],a:1,e:'Aucune cote n’a été confirmée ; le contenu sur le renseignement est ici de seconde main.'}
];
